public class Fee {
    static int fee(int weightKg) {
        final int fee;
        if (weightKg <= 5) {
            fee = 499;
        } else if (weightKg > 5) {
            fee = 999;
        }
        return fee;
    }
}

static final boolean TRACE = false;

static void handle(String request) {
    if (TRACE) {
        System.out.println("handling " + request);
    }
}

static int length(Object payload) {
    if (!(payload instanceof String text)) {
        return -1;
    }
    return text.length();
}
